public class InnerRegistryRecordMcpServerDescriptorFactory(Action<Humidifier.AgentRegistry.RegistryRecordTypes.McpServerDescriptor> factoryAction = null) : SubResourceFactory<Humidifier.AgentRegistry.RegistryRecordTypes.McpServerDescriptor>
{

    internal InnerRegistryRecordMcpServerAdditionalDataFactory AdditionalDataFactory { get; set; }

    internal InnerRegistryRecordDescriptorSourceFactory SourceFactory { get; set; }

    protected override Humidifier.AgentRegistry.RegistryRecordTypes.McpServerDescriptor Create()
    {
        var mcpServerDescriptorResult = CreateMcpServerDescriptor();
        factoryAction?.Invoke(mcpServerDescriptorResult);

        return mcpServerDescriptorResult;
    }

    private Humidifier.AgentRegistry.RegistryRecordTypes.McpServerDescriptor CreateMcpServerDescriptor()
    {
        var mcpServerDescriptorResult = new Humidifier.AgentRegistry.RegistryRecordTypes.McpServerDescriptor();

        return mcpServerDescriptorResult;
    }
    public override void CreateChildren(Humidifier.AgentRegistry.RegistryRecordTypes.McpServerDescriptor result)
    {
        base.CreateChildren(result);

        result.AdditionalData ??= AdditionalDataFactory?.Build();
        result.Source ??= SourceFactory?.Build();
    }

} // End Of Class

